import hashlib

def hash_data(data: str) -> str:
    return hashlib.sha256(data.encode('utf-8')).hexdigest()

def build_merkle_tree(leaves: list[str]) -> list[list[str]]:
    if not leaves:
        return [[]]
    current = [hash_data(x) for x in leaves]
    levels = [current]
    while len(current) > 1:
        next_level = []
        for i in range(0, len(current), 2):
            left = current[i]
            right = current[i + 1] if i + 1 < len(current) else current[i]
            next_level.append(hash_data(left + right))
        levels.append(next_level)
        current = next_level
    return levels

def get_merkle_root(leaves: list[str]) -> str:
    levels = build_merkle_tree(leaves)
    return levels[-1][0] if levels and levels[-1] else ""

def generate_audit_proof(leaves: list[str], index: int) -> list[tuple[str, str]]:
    levels = build_merkle_tree(leaves)
    proof = []
    curr_idx = index
    for l in range(len(levels) - 1):
        level = levels[l]
        if curr_idx % 2 == 0:
            sibling_idx = curr_idx + 1 if curr_idx + 1 < len(level) else curr_idx
            proof.append((level[sibling_idx], 'right'))
        else:
            sibling_idx = curr_idx - 1
            proof.append((level[sibling_idx], 'left'))
        curr_idx //= 2
    return proof

def verify_audit_proof(leaf: str, proof: list[tuple[str, str]], root: str) -> bool:
    curr_hash = hash_data(leaf)
    for sibling_hash, direction in proof:
        if direction == 'right':
            curr_hash = hash_data(curr_hash + sibling_hash)
        else:
            curr_hash = hash_data(sibling_hash + curr_hash)
    return curr_hash == root
